int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    struct sctp_association *asoc;
    struct sctp_assoc_stats stats;
    int ret = 0;

    if (len < sizeof(stats.assoc_id)) {
        return -EINVAL;
    }

    if (copy_from_user(&stats.assoc_id, optval, sizeof(stats.assoc_id))) {
        return -EFAULT;
    }

    asoc = sctp_id2assoc(sk, stats.assoc_id);
    if (!asoc) {
        return -EINVAL;
    }

    stats.cumulative_tsn = asoc->cumulative_tsn;
    stats.retransmitted_tsn = asoc->retrans_tsn;
    stats.retransmitted_packets = asoc->retrans_packets;
    stats.retransmitted_bytes = asoc->retrans_bytes;
    stats.rto_min = asoc->rto_min;
    stats.rto_max = asoc->rto_max;
    stats.rto_current = asoc->rto;
    stats.max_rto = asoc->max_rto;
    stats.min_rto = asoc->min_rto;

    if (asoc->rto > asoc->max_rto) {
        asoc->max_rto = asoc->rto;
    }

    if (copy_to_user(optval, &stats, sizeof(stats))) {
        return -EFAULT;
    }

    if (put_user(sizeof(stats), optlen)) {
        return -EFAULT;
    }

    return ret;
}

