int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen)
{
    int err = 0;
    struct sctp_assoc_stats __user *u_stats = (struct sctp_assoc_stats __user *)optval;
    struct sctp_assoc_stats stats;

    if (len < sizeof(stats.assoc_id)) {
        return -EINVAL;
    }

    if (copy_from_user(&stats.assoc_id, &u_stats->assoc_id, sizeof(stats.assoc_id))) {
        return -EFAULT;
    }

    /* Retrieve association statistics based on the association ID */
    struct sctp_association *asoc = sctp_id2assoc(sk, stats.assoc_id);
    if (!asoc) {
        return -ENOENT;
    }

    stats.cwnd = asoc->cwnd;
    stats.ssthresh = asoc->ssthresh;
    stats.pmtu = asoc->pmtu;
    stats.rtx_cnt = asoc->stats->sctpRetransmits;
    stats.t1expired = asoc->stats->sctpT1Expired;
    stats.t2expired = asoc->stats->sctpT2Expired;
    stats.t3expired = asoc->stats->sctpT3Expired;
    stats.t4expired = asoc->stats->sctpT4Expired;
    stats.pmtud_discards = asoc->stats->sctpPmtudDiscards;
    stats.data_pkts = asoc->stats->sctpDataPacketsSent;
    stats.data_bytes = asoc->stats->sctpOutBytes;
    stats.retransmits = asoc->stats->sctpRetransmits;
    stats.retrans_bytes = asoc->stats->sctpRetransBytes;
    stats.sacks = asoc->stats->sctpSacks;
    stats.reord_pkts = asoc->stats->sctpReorderPkts;
    stats.reord_bytes = asoc->stats->sctpReorderBytes;
    stats.dup_pkts = asoc->stats->sctpDuplicates;
    stats.dup_bytes = asoc->stats->sctpDuplicatesBytes;
    stats.aborts = asoc->stats->sctpAborts;
    stats.shutdwns = asoc->stats->sctpShutDowns;

    stats.max_rto = asoc->rto_max;

    if (copy_to_user(u_stats, &stats, sizeof(stats))) {
        return -EFAULT;
    }

    if (put_user(sizeof(stats), optlen)) {
        return -EFAULT;
    }

    return 0;
}
